flow.typescript:
// D14 · Part 0~9 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d14_flow.ts   (모의 받아쓰기 결과 · 인터넷·GPU·API 키 불필요)
//   같은 시험지로 채점(정규화) → 비용 계산(과금 단위 올림) → 리더보드 → 부트스트랩 신뢰구간 → 오류 종류 → 모델 카드 성능표 순서로 한 번에 돈다
//   흉내 낸 부분: 실제 모델 · API 대신 글자를 일정 확률로 틀리게 만든 결과, API 가격은 강의용 가정값
const TERMS = ["심방세동", "와파린", "트로포닌", "크레아티닌", "패혈증", "대상포진", "항응고제", "당화혈색소"];
const TPL = ["기록지에 {t} 항목을 표시해 주세요", "{t} 경과를 내일 다시 보겠습니다", "고객에게 {t} 설명을 드렸습니다"];
type Row = { text: string; term: string };
const ROWS: Row[] = [...TPL.flatMap((t) => TERMS.map((w) => ({ text: t.replace("{t}", w), term: w }))), ...TPL.flatMap((t) => TERMS.map((w) => ({ text: t.replace("{t}", w), term: w })))]; // 도메인 문장 48개(합성음 두 목소리 가정)
const SYSTEMS: Record<string, number> = { "① 원래 Whisper": 0.4, "③ D13 LoRA": 0.04, "OpenAI API": 0.2 }; // 용어 글자 오류율
const FILL = [..."가나다라마바사아자차"];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0);
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;

const normalize = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, ""); // 모든 시스템에 똑같이 적용하는 채점 기준

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return d[b.length];
}

function corrupt(row: Row, termRate: number): string {
  const a = row.text.indexOf(row.term);
  return [...row.text].map((c, i) => (i >= a && i < a + row.term.length && rnd() < termRate ? FILL[Math.floor(rnd() * FILL.length)] : c)).join("");
}

const PRED = Object.fromEntries(Object.entries(SYSTEMS).map(([n, rate]) => [n, ROWS.map((r) => corrupt(r, rate))]));
const perCer = Object.fromEntries(Object.entries(PRED).map(([n, ps]) => [n, ps.map((p, i) => (100 * editDistance(normalize(ROWS[i].text), normalize(p))) / normalize(ROWS[i].text).length)]));
const termHit = Object.fromEntries(Object.entries(PRED).map(([n, ps]) => [n, ps.map((p, i) => (normalize(p).includes(normalize(ROWS[i].term)) ? 100 : 0))]));

// 비용: 문장 평균 4초, 15초 단위 올림 가정의 서비스까지 비교
const durs = ROWS.map(() => 4.0);
const total = durs.reduce((a, b) => a + b, 0);
const unitCost = { "OpenAI API": (total / 3600) * 0.27, "15초 단위 서비스": (durs.reduce((s, d) => s + Math.ceil(d / 15) * 15, 0) / 3600) * 0.27 };
console.log("비용(USD):", Object.fromEntries(Object.entries(unitCost).map(([k, v]) => [k, Math.round(v * 1000) / 1000])));

console.log("시스템".padEnd(16) + "CER(%)".padStart(8) + "용어(%)".padStart(9));
for (const n of Object.keys(SYSTEMS)) console.log(n.padEnd(16) + mean(perCer[n]).toFixed(2).padStart(8) + mean(termHit[n]).toFixed(1).padStart(9));

function bootstrap(a: number[], b: number[], nBoot: number = 2000): [number, number, number] {
  const g = mulberry32(0);
  const diffs: number[] = [];
  for (let k = 0; k < nBoot; k++) {
    const idx = Array.from({ length: a.length }, () => Math.floor(g() * a.length));
    diffs.push(mean(idx.map((i) => a[i])) - mean(idx.map((i) => b[i])));
  }
  diffs.sort((x, y) => x - y);
  const q = (p: number): number => {
    const pos = ((diffs.length - 1) * p) / 100;
    const lo = Math.floor(pos);
    return diffs[lo] + (diffs[Math.min(lo + 1, diffs.length - 1)] - diffs[lo]) * (pos - lo);
  };
  return [mean(a) - mean(b), q(2.5), q(97.5)];
}

const base = "① 원래 Whisper", mine = "③ D13 LoRA";
const [diff, lo, hi] = bootstrap(perCer[base], perCer[mine]);
const verdict = lo > 0 ? "개선 ✓" : hi < 0 ? "악화 ✗" : "차이 불확실";
console.log(`CER 원래 − LoRA = ${diff.toFixed(2)}%p, 95% [${lo.toFixed(2)}, ${hi.toFixed(2)}] → ${verdict}`);
const missTerms = [...new Set(ROWS.filter((_, i) => termHit[mine][i] === 0).map((r) => r.term))].sort();
console.log("LoRA가 아직 틀리는 용어:", missTerms.length ? missTerms : "없음");
console.log(`모델 카드 성능표 한 줄: | ${mine} | ${mean(perCer[mine]).toFixed(2)} | ${mean(termHit[mine]).toFixed(1)} |`);
check(ROWS.length === 48 && verdict === "개선 ✓" && mean(termHit[mine]) > mean(termHit[base]) + 20 && unitCost["15초 단위 서비스"] > 3 * unitCost["OpenAI API"],
  "LoRA는 같은 시험지에서 개선 ✓ 이고, 15초 단위 과금은 4초 발화에서 약 3.75배 비싸야 해요.");

fair.typescript:
// D14 · Part 1 · 공정한 비교의 규칙 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d14_fair.ts   (모의 받아쓰기 결과 · 인터넷·GPU 불필요)
//   같은 시험지 · 같은 정규화로 채점하지 않으면 순위가 뒤집히는 것을 보인다 (문장 부호 · 띄어쓰기를 지우기 전 vs 후)
//   흉내 낸 부분: 두 시스템의 결과를 손으로 만든 문장으로 대신함 (A는 정확하지만 문장 부호를 붙여 줌, B는 한 글자 틀리지만 부호가 없음)
const REFS = ["오늘 회의는 세 시에 시작합니다", "다음 주까지 자료를 정리해 주세요", "혈압을 다시 재겠습니다", "일정은 그대로 진행합니다"];
const SYS_A = ["오늘 회의는 세 시에 시작합니다.", "다음 주까지 자료를 정리해 주세요.", "혈압을 다시 재겠습니다.", "일정은 그대로 진행합니다."]; // 글자는 모두 맞고 마침표만 붙음
const SYS_B = ["오늘 회의는 세 시에 시작합니다", "다음 주까지 자료를 정리해 주세오", "혈압을 다시 재겠습니다", "일정은 그대로 진행합니다"]; // 한 글자 틀림, 부호 없음

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function normalize(s: string): string {
  // 모든 시스템에 똑같이 적용하는 채점 기준
  return s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");
}

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return d[b.length];
}

function cer(refs: string[], preds: string[]): number {
  // 글자 오류율(%) = 편집 거리 합 ÷ 정답 글자 수 합
  return (100 * refs.reduce((s, r, i) => s + editDistance(r, preds[i]), 0)) / refs.reduce((s, r) => s + r.length, 0);
}
const cerRaw = (p: string[]): number => cer(REFS, p); // 정규화 없이 그대로 채점
const cerNorm = (p: string[]): number => cer(REFS.map(normalize), p.map(normalize));

console.log("".padEnd(6) + "정규화 전 CER".padStart(14) + "정규화 후 CER".padStart(14));
for (const [name, p] of [["A", SYS_A], ["B", SYS_B]] as [string, string[]][]) {
  console.log(name.padEnd(6) + `${cerRaw(p).toFixed(2)}%`.padStart(14) + `${cerNorm(p).toFixed(2)}%`.padStart(14));
}
const rawWinner = cerRaw(SYS_A) < cerRaw(SYS_B) ? "A" : "B";
const normWinner = cerNorm(SYS_A) < cerNorm(SYS_B) ? "A" : "B";
console.log(`정규화 전 승자 ${rawWinner} · 정규화 후 승자 ${normWinner}`);
console.log("공정한 비교 규칙:", ["같은 시험 문장", "같은 정규화(문장 부호 · 띄어쓰기)", "같은 지표(CER)", "시험 문장은 학습에 쓰지 않기"].join(" / "));
check(rawWinner === "B" && normWinner === "A" && cerNorm(SYS_A) === 0,
  "정규화 전에는 부호가 붙은 A가 불리해 B가 이기고, 정규화 후에는 글자가 모두 맞은 A가 이겨야 해요.");

latency.typescript:
// D14 · Part 3 · RTF와 지연 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d14_latency.ts   (몇 초 · GPU·인터넷·모델 불필요)
//   RTF = 처리 시간 ÷ 소리 길이. 소리 길이를 바꿔 재 보고, 요청마다 고정 비용이 있어 묶음(batch)이 유리한 것과 p50 · p95 지연을 계산한다
//   흉내 낸 부분: 받아쓰기 모델 대신 소리 길이에 비례해 프레임 에너지를 계산하는 함수(처리 시간 측정 연습용), 요청 고정 비용은 잠깐 멈추기(sleep)로 흉내
const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const sleep = (ms: number): void => {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); // 지정한 시간만큼 멈춤
};

function fakeAsr(y: Float32Array): number {
  // 소리 길이에 비례하는 일을 한 뒤 처리에 걸린 초를 돌려준다
  const t0 = performance.now();
  let sink = 0;
  for (let i = 0; i + 512 <= y.length; i += 256) {
    for (let k = 0; k < 512; k++) sink += Math.abs(y[i + k]) * Math.cos(k * 0.01); // 프레임마다 계산 (길수록 오래 걸림)
  }
  if (sink === Infinity) console.log(sink);
  return (performance.now() - t0) / 1000;
}

const durs = [2, 4, 8, 16];
const rtfs: number[] = [];
for (const d of durs) {
  const y = Float32Array.from({ length: d * SR }, (_, i) => 0.1 * Math.sin(i * 0.37));
  const proc = Math.min(fakeAsr(y), fakeAsr(y), fakeAsr(y)); // 3번 중 가장 빠른 값(잡음 줄이기)
  rtfs.push(proc / d);
  console.log(`소리 ${d.toFixed(1).padStart(5)}초 → 처리 ${proc.toFixed(3)}초 → RTF ${(proc / d).toFixed(4)}`);
}
console.log("RTF < 1 이면 실시간보다 빠름:", rtfs.every((r) => r < 1));

const OVERHEAD = 20; // 요청 하나마다 드는 고정 비용(밀리초): 모델 준비 · 네트워크 왕복 흉내
const timed = (fn: () => void): number => {
  const t0 = performance.now();
  fn();
  return (performance.now() - t0) / 1000;
};
const singles = Array.from({ length: 8 }, () => timed(() => sleep(OVERHEAD)));
const batchTotal = timed(() => sleep(OVERHEAD)); // 묶음은 고정 비용을 한 번만 냄
const singleSum = singles.reduce((a, b) => a + b, 0);
console.log(`8개를 하나씩 ${singleSum.toFixed(3)}초 · 한 묶음으로 ${batchTotal.toFixed(3)}초`);

function percentile(values: number[], q: number): number {
  const s = [...values].sort((a, b) => a - b);
  const pos = ((s.length - 1) * q) / 100; // 선형 보간
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}
const lat = [0.31, 0.28, 0.35, 0.30, 0.29, 1.20, 0.33, 0.32, 0.30, 0.34]; // 요청당 지연 예시(초): 한 번 느린 요청이 섞임
const mean = lat.reduce((a, b) => a + b, 0) / lat.length;
const [p50, p95] = [percentile(lat, 50), percentile(lat, 95)];
console.log(`지연 평균 ${mean.toFixed(2)}초 · p50 ${p50.toFixed(2)}초 · p95 ${p95.toFixed(2)}초 (평균은 느린 요청에 끌려가고 p50은 보통 요청을 보여 줌)`);
check(rtfs.every((r) => r < 1) && Math.max(...rtfs) < 20 * Math.min(...rtfs) && batchTotal < singleSum / 4 && p95 > 2 * p50 && mean > p50,
  "RTF는 길이와 거의 무관한 값이고, 묶음이 하나씩보다 빠르며, p95가 p50보다 훨씬 커야 해요.");

api.typescript:
// D14 · Part 4 · API 요청 해부 (OpenAI · Google · CLOVA) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d14_api.ts          → 키 없이 내 컴퓨터의 모의 서버로 요청 모양만 검증
//       node --experimental-strip-types d14_api.ts --real   → API 키 환경 변수(OPENAI_API_KEY · GOOGLE_API_KEY · CLOVA_*)가 있는 서비스는 진짜 주소로 전송
//   세 서비스의 요청(주소 · 헤더 · 본문)을 만들고, 모의 서버가 필수 항목(언어 ko, 인코딩, 키 헤더)을 제대로 받았는지 확인한다
//   흉내 낸 부분: 기본 실행은 진짜 서비스 대신 같은 주소 모양의 모의 서버(127.0.0.1)와 합성 WAV. 응답 글자도 모의 서버가 정해서 줌
import http from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const REAL = process.argv.includes("--real");
const env = (k: string): string | undefined => process.env[k];
const seen: [string, boolean][] = []; // 모의 서버가 받은 요청 기록

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function makeWav(): Buffer {
  const data = Buffer.alloc(SR * 2);
  for (let i = 0; i < SR; i++) data.writeInt16LE(Math.round(0.3 * 32767 * Math.sin((2 * Math.PI * 300 * i) / SR)), i * 2);
  const h = Buffer.alloc(44);
  h.write("RIFF", 0); h.writeUInt32LE(36 + data.length, 4); h.write("WAVEfmt ", 8); h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20); h.writeUInt16LE(1, 22); h.writeUInt32LE(SR, 24); h.writeUInt32LE(SR * 2, 28);
  h.writeUInt16LE(2, 32); h.writeUInt16LE(16, 34); h.write("data", 36); h.writeUInt32LE(data.length, 40);
  return Buffer.concat([h, data]);
}

type Req = { url: string; headers: Record<string, string>; body: FormData | string | Buffer };

function openaiRequest(wav: Buffer, base: string): Req {
  const form = new FormData(); // multipart/form-data 는 fetch가 경계(boundary)까지 만들어 줌
  form.append("model", "gpt-transcribe");
  form.append("languages[]", "ko");
  form.append("file", new Blob([new Uint8Array(wav)], { type: "audio/wav" }), "audio.wav");
  return { url: `${base}/v1/audio/transcriptions`, headers: { Authorization: `Bearer ${env("OPENAI_API_KEY") ?? "test-key"}` }, body: form };
}

function googleRequest(wav: Buffer, base: string): Req {
  const cfg = { config: { encoding: "LINEAR16", sampleRateHertz: SR, languageCode: "ko-KR" }, audio: { content: wav.toString("base64") } };
  return { url: `${base}/v1/speech:recognize?key=${env("GOOGLE_API_KEY") ?? "test-key"}`, headers: { "Content-Type": "application/json" }, body: JSON.stringify(cfg) };
}

function clovaRequest(wav: Buffer, base: string): Req {
  return {
    url: `${base}/recog/v1/stt?lang=Kor`,
    headers: { "X-NCP-APIGW-API-KEY-ID": env("CLOVA_CLIENT_ID") ?? "id", "X-NCP-APIGW-API-KEY": env("CLOVA_CLIENT_SECRET") ?? "secret", "Content-Type": "application/octet-stream" },
    body: wav,
  };
}

function startMock(): Promise<http.Server> {
  const server = http.createServer((req, res) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", () => {
      const body = Buffer.concat(chunks);
      const path = (req.url ?? "").split("?")[0];
      let out: unknown;
      if (path === "/v1/audio/transcriptions") { // 서비스마다 '필수 항목'이 들어왔는지 기록
        seen.push(["openai", body.includes('name="languages[]"\r\n\r\nko') && body.includes('name="file"') && String(req.headers.authorization).startsWith("Bearer ")]);
        out = { text: "모의 응답 openai" };
      } else if (path === "/v1/speech:recognize") {
        const j = JSON.parse(body.toString());
        seen.push(["google", j.config.languageCode === "ko-KR" && Buffer.from(j.audio.content, "base64").subarray(0, 4).toString() === "RIFF" && (req.url ?? "").includes("key=")]);
        out = { results: [{ alternatives: [{ transcript: "모의 응답 google" }] }] };
