# 실행: python d14_leaderboard.py   (모의 받아쓰기 결과 · 인터넷·GPU 불필요)
#   같은 시험지(일반 12문장 + 도메인 24문장)로 시스템 4개를 채점해 한 표로 모으고, 비용과 성능을 함께 보는 '최선 후보(파레토)'를 찾는다
#   흉내 낸 부분: 실제 모델 · API 대신 글자를 일정 확률로 틀리게 만든 결과(시스템마다 틀리는 확률을 정해 둠)
import re

import jiwer
import numpy as np

rng = np.random.default_rng(0)
TERMS = ["심방세동", "와파린", "트로포닌", "크레아티닌", "패혈증", "대상포진", "항응고제", "당화혈색소"]
TPL = ["기록지에 {t} 항목을 표시해 주세요", "{t} 경과를 내일 다시 보겠습니다", "고객에게 {t} 설명을 드렸습니다"]
GEN = ["오늘 날씨가 정말 좋네요", "회의는 세 시에 시작합니다", "점심 같이 먹을래요", "내일 아침에 다시 연락드리겠습니다"]
ROWS = [dict(text=g, term="", set="일반") for g in GEN * 3] + [dict(text=t.format(t=w), term=w, set="도메인") for t in TPL for w in TERMS]
SYSTEMS = {  # 일반 글자 오류율, 용어 글자 오류율, RTF, 소리 1시간당 USD, 소리 외부 전송
    "① 원래 Whisper": (0.05, 0.50, 0.15, 0.0, False),
    "② D13 LoRA": (0.05, 0.05, 0.15, 0.0, False),
    "OpenAI API": (0.02, 0.25, None, 0.27, True),
    "CLOVA API": (0.03, 0.30, None, 0.43, True),
}
FILL = list("가나다라마바사아자차카타파하")


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def normalize(s: str) -> str:
    return re.sub(r"\s+", "", re.sub(r"[^\w\s]", "", s.lower()))


def corrupt(row: dict, gen_rate: float, term_rate: float) -> str:
    out = []
    for i, c in enumerate(row["text"]):
        in_term = bool(row["term"]) and row["text"].find(row["term"]) <= i < row["text"].find(row["term"]) + len(row["term"])
        out.append(FILL[rng.integers(len(FILL))] if rng.random() < (term_rate if in_term else gen_rate) else c)
    return "".join(out)


PRED = {n: [corrupt(r, s[0], s[1]) for r in ROWS] for n, s in SYSTEMS.items()}


def cer(idx: list, preds: list) -> float:
    return 100 * jiwer.cer([normalize(ROWS[i]["text"]) for i in idx], [normalize(preds[i]) or "∅" for i in idx])


def term_acc(idx: list, preds: list) -> float:
    return 100 * float(np.mean([normalize(ROWS[i]["term"]) in normalize(preds[i]) for i in idx]))


gi = [i for i, r in enumerate(ROWS) if r["set"] == "일반"]
di = [i for i, r in enumerate(ROWS) if r["set"] == "도메인"]
board = {n: dict(gen=cer(gi, p), dom=cer(di, p), term=term_acc(di, p), rtf=SYSTEMS[n][2], usd=SYSTEMS[n][3], ext=SYSTEMS[n][4]) for n, p in PRED.items()}
print(f"{'시스템':16s}{'일반CER':>8s}{'도메인CER':>10s}{'용어%':>7s}{'RTF':>6s}{'USD/시간':>9s} 외부전송")
for n, r in sorted(board.items(), key=lambda kv: kv[1]["gen"]):
    print(f"{n:16s}{r['gen']:8.2f}{r['dom']:10.2f}{r['term']:7.1f}{r['rtf'] if r['rtf'] else '-':>6}{r['usd']:9.2f} {'예' if r['ext'] else '아니요'}")


def pareto(items: dict) -> list:
    """비용도 낮고(USD) 도메인 CER도 낮은 쪽에 '둘 다 더 나은' 시스템이 없는 후보."""
    return [a for a, x in items.items() if not any(b != a and y["usd"] <= x["usd"] and y["dom"] <= x["dom"] and (y["usd"] < x["usd"] or y["dom"] < x["dom"]) for b, y in items.items())]


front = pareto(board)
print("최선 후보(비용 · 도메인 CER 기준):", front)
check(len(ROWS) == 36 and board["② D13 LoRA"]["term"] > board["① 원래 Whisper"]["term"] + 20 and "② D13 LoRA" in front and "① 원래 Whisper" not in front,
      "LoRA가 용어 정확도를 크게 올리고, 비용 0에 도메인 CER도 낮아 최선 후보에 들어야 해요.")

