// D14 · Part 5 · 나만의 리더보드 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d14_leaderboard.ts   (모의 받아쓰기 결과 · 인터넷·GPU 불필요)
//   같은 시험지(일반 12문장 + 도메인 24문장)로 시스템 4개를 채점해 한 표로 모으고, 비용과 성능을 함께 보는 '최선 후보(파레토)'를 찾는다
//   흉내 낸 부분: 실제 모델 · API 대신 글자를 일정 확률로 틀리게 만든 결과(시스템마다 틀리는 확률을 정해 둠)
const TERMS = ["심방세동", "와파린", "트로포닌", "크레아티닌", "패혈증", "대상포진", "항응고제", "당화혈색소"];
const TPL = ["기록지에 {t} 항목을 표시해 주세요", "{t} 경과를 내일 다시 보겠습니다", "고객에게 {t} 설명을 드렸습니다"];
const GEN = ["오늘 날씨가 정말 좋네요", "회의는 세 시에 시작합니다", "점심 같이 먹을래요", "내일 아침에 다시 연락드리겠습니다"];
type Row = { text: string; term: string; set: string };
const ROWS: Row[] = [
  ...[...GEN, ...GEN, ...GEN].map((text) => ({ text, term: "", set: "일반" })),
  ...TPL.flatMap((t) => TERMS.map((w) => ({ text: t.replace("{t}", w), term: w, set: "도메인" }))),
];
const SYSTEMS: Record<string, { gen: number; term: number; rtf: number | null; usd: number; ext: boolean }> = { // 일반 글자 오류율, 용어 글자 오류율, RTF, 소리 1시간당 USD, 소리 외부 전송
  "① 원래 Whisper": { gen: 0.05, term: 0.5, rtf: 0.15, usd: 0, ext: false },
  "② D13 LoRA": { gen: 0.05, term: 0.05, rtf: 0.15, usd: 0, ext: false },
  "OpenAI API": { gen: 0.02, term: 0.25, rtf: null, usd: 0.27, ext: true },
  "CLOVA API": { gen: 0.03, term: 0.3, rtf: null, usd: 0.43, ext: true },
};
const FILL = [..."가나다라마바사아자차카타파하"];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0);

const normalize = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return d[b.length];
}

function corrupt(row: Row, genRate: number, termRate: number): string {
  const a = row.term ? row.text.indexOf(row.term) : -1;
  return [...row.text].map((c, i) => {
    const inTerm = a >= 0 && i >= a && i < a + row.term.length;
    return rnd() < (inTerm ? termRate : genRate) ? FILL[Math.floor(rnd() * FILL.length)] : c;
  }).join("");
}

const PRED: Record<string, string[]> = Object.fromEntries(Object.entries(SYSTEMS).map(([n, s]) => [n, ROWS.map((r) => corrupt(r, s.gen, s.term))]));

function cer(idx: number[], preds: string[]): number {
  const refs = idx.map((i) => normalize(ROWS[i].text));
  const errs = idx.reduce((s, i, k) => s + editDistance(refs[k], normalize(preds[i]) || "∅"), 0);
  return (100 * errs) / refs.reduce((s, r) => s + r.length, 0);
}
const termAcc = (idx: number[], preds: string[]): number => (100 * idx.filter((i) => normalize(preds[i]).includes(normalize(ROWS[i].term))).length) / idx.length;

const gi = ROWS.map((r, i) => (r.set === "일반" ? i : -1)).filter((i) => i >= 0);
const di = ROWS.map((r, i) => (r.set === "도메인" ? i : -1)).filter((i) => i >= 0);
const board = Object.fromEntries(Object.entries(PRED).map(([n, p]) => [n, { gen: cer(gi, p), dom: cer(di, p), term: termAcc(di, p), rtf: SYSTEMS[n].rtf, usd: SYSTEMS[n].usd, ext: SYSTEMS[n].ext }]));
console.log("시스템".padEnd(16) + "일반CER".padStart(8) + "도메인CER".padStart(10) + "용어%".padStart(7) + "RTF".padStart(6) + "USD/시간".padStart(9) + " 외부전송");
for (const [n, r] of Object.entries(board).sort((a, b) => a[1].gen - b[1].gen)) {
  console.log(n.padEnd(16) + r.gen.toFixed(2).padStart(8) + r.dom.toFixed(2).padStart(10) + r.term.toFixed(1).padStart(7) + String(r.rtf ?? "-").padStart(6) + r.usd.toFixed(2).padStart(9) + ` ${r.ext ? "예" : "아니요"}`);
}

function pareto(items: typeof board): string[] {
  // 비용도 낮고(USD) 도메인 CER도 낮은 쪽에 '둘 다 더 나은' 시스템이 없는 후보
  return Object.keys(items).filter((a) => !Object.keys(items).some((b) => b !== a && items[b].usd <= items[a].usd && items[b].dom <= items[a].dom && (items[b].usd < items[a].usd || items[b].dom < items[a].dom)));
}
const front = pareto(board);
console.log("최선 후보(비용 · 도메인 CER 기준):", front);
check(ROWS.length === 36 && board["② D13 LoRA"].term > board["① 원래 Whisper"].term + 20 && front.includes("② D13 LoRA") && !front.includes("① 원래 Whisper"),
  "LoRA가 용어 정확도를 크게 올리고, 비용 0에 도메인 CER도 낮아 최선 후보에 들어야 해요.");

