//   흉내 낸 부분: 실제 모델 결과 대신 평균 3%p 개선되도록 만든 문장별 CER(잡음 포함)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0);
const gauss = (mean: number, sd: number): number => mean + sd * Math.sqrt(-2 * Math.log(Math.max(rnd(), 1e-12))) * Math.cos(2 * Math.PI * rnd());
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;

function percentile(values: number[], q: number): number {
  const s = [...values].sort((a, b) => a - b);
  const pos = ((s.length - 1) * q) / 100; // 선형 보간
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

function bootstrapDiff(a: number[], b: number[], nBoot: number = 2000, seed: number = 0): { d: number; lo: number; hi: number; diffs: number[] } {
  const g = mulberry32(seed);
  const n = a.length;
  const diffs: number[] = [];
  for (let k = 0; k < nBoot; k++) {
    const idx = Array.from({ length: n }, () => Math.floor(g() * n)); // 같은 문장 번호로 두 시스템을 함께 뽑음(짝지은 비교)
    diffs.push(mean(idx.map((i) => a[i])) - mean(idx.map((i) => b[i])));
  }
  return { d: mean(a) - mean(b), lo: percentile(diffs, 2.5), hi: percentile(diffs, 97.5), diffs };
}

const verdict = (lo: number, hi: number): string => (lo > 0 ? "개선 ✓" : hi < 0 ? "악화 ✗" : "차이 불확실");

function sample(n: number, gain: number): [number[], number[]] {
  const base = Array.from({ length: n }, () => Math.max(0, gauss(10, 6))); // 원래 시스템의 문장별 CER(%)
  const ours = base.map((v) => Math.max(0, v - gain + gauss(0, 3))); // 우리 시스템: 평균 gain만큼 낮지만 문장마다 들쭉날쭉
  return [base, ours];
}

console.log("조건".padEnd(22) + "평균 차이".padStart(9) + "95% 하한".padStart(9) + "95% 상한".padStart(9) + "  판정");
const res = new Map<string, [number, number]>();
for (const [name, n, gain] of [["문장 10개 · 3%p 개선", 10, 3], ["문장 200개 · 3%p 개선", 200, 3], ["문장 200개 · 변화 없음", 200, 0]] as [string, number, number][]) {
  const [a, b] = sample(n, gain);
  const { d, lo, hi } = bootstrapDiff(a, b);
  res.set(name, [lo, hi]);
  console.log(name.padEnd(22) + d.toFixed(2).padStart(9) + lo.toFixed(2).padStart(9) + hi.toFixed(2).padStart(9) + `  ${verdict(lo, hi)}`);
}

const t = bootstrapDiff(Array(20).fill([5, 3, 8, 0, 2]).flat(), Array(20).fill([4, 3, 6, 1, 2]).flat());
const [r10, r200, r0] = [res.get("문장 10개 · 3%p 개선"), res.get("문장 200개 · 3%p 개선"), res.get("문장 200개 · 변화 없음")] as [number, number][];
const [w10, w200] = [r10[1] - r10[0], r200[1] - r200[0]];
console.log(`구간 너비: 10개 ${w10.toFixed(2)} vs 200개 ${w200.toFixed(2)}`);
check(t.diffs.length === 2000 && t.lo <= mean(t.diffs) && mean(t.diffs) <= t.hi && t.hi - t.lo < 1.5 && w10 > 2 * w200 && r200[0] > 0 && r0[0] < 0 && 0 < r0[1],
