//   흉내 낸 부분: 두 시스템(원래 모델 · LoRA)의 받아쓰기 결과를 문장 8개에 대해 직접 적어 둠
const ROWS: [string, string][] = [ // 정답, 용어(없으면 빈 문자열)
  ["기록지에 심방세동 항목을 표시해 주세요", "심방세동"], ["와파린 경과를 내일 다시 보겠습니다", "와파린"], ["고객에게 트로포닌 설명을 드렸습니다", "트로포닌"],
  ["회의는 3시에 시작합니다", ""], ["오늘 날씨가 정말 좋네요", ""], ["다음 주까지 자료를 정리해 주세요", ""],
  ["크레아티닌 수치를 확인했습니다", "크레아티닌"], ["점심 같이 먹을래요", ""],
];
const PRED: Record<string, string[]> = {
  원래: ["기록지에 심방 새동 항목을 표시해 주세요", "와파린 경과를 내일 다시 보겠습니다", "고객에게 트로포닌 설명을 드렸습니다",
