  LoRA: ["기록지에 심방세동 항목을 표시해 주세요", "와파린 경과를 내일 다시 보겠습니다", "고객에게 트로포닌 설명을 드렸습니다",
    "회의는 3시에 시작합니다", "오늘 날씨가 정말 좋네", "다음 주까지 자료 정리", "크레아티닌 수치를 확인했습니다", "점심 같이 먹을래요"],
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const normalize = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return d[b.length];
}

function cer(ref: string, pred: string): number {
  const r = normalize(ref);
  return editDistance(r, normalize(pred) || "∅") / r.length;
}

function errorType(text: string, term: string, pred: string): string | null {
  const c = cer(text, pred);
  if (c === 0) return null;
  if (term && !normalize(pred).includes(normalize(term))) return "용어";
  if (/\d/.test(text + pred)) return "숫자 표기";
  return c > 0.5 ? "크게 틀림" : "일부 글자";
}

const counts: Record<string, Record<string, number>> = {};
