}

const usage = `from transformers import WhisperForConditionalGeneration\nfrom peft import PeftModel\nbase = WhisperForConditionalGeneration.from_pretrained("${CFG.modelName}")\nmodel = PeftModel.from_pretrained(base, "REPO_ID")`;
